const sources=[
 {id:1,type:'pdf',title:'The Bitter Lesson',desc:'Escalabilidad, cómputo y métodos generales en sistemas inteligentes.',date:'HOY',tags:['IA','escalabilidad'],links:7,author:'Rich Sutton',url:'incompleteideas.net',summary:'Los métodos que aprovechan el cómputo terminan superando a los enfoques basados en conocimiento humano específico. La lección práctica es construir sistemas que puedan escalar con recursos y datos.',quote:'La búsqueda y el aprendizaje son los dos métodos que parecen escalar arbitrariamente con más cómputo.',related:['Scaling Laws for Neural Language Models','Compute Trends Across Three Eras']},
 {id:2,type:'link',title:'Tools for thought as cultural practices',desc:'Una lectura sobre cómo las herramientas cambian la manera de producir conocimiento.',date:'AYER',tags:['PKM','cultura'],links:5,author:'Maggie Appleton',url:'maggieappleton.com',summary:'Las herramientas para pensar no son contenedores neutrales: codifican prácticas, valores y relaciones sociales. Su valor emerge cuando se integran en hábitos sostenidos.',quote:'Una herramienta se vuelve infraestructura cuando deja de sentirse como una herramienta.',related:['How to Make Yourself Into a Learning Machine','The Garden and the Stream']},
 {id:3,type:'note',title:'Hipótesis: la síntesis es una interfaz',desc:'Notas propias sobre navegación semántica y reducción de fricción.',date:'28 OCT',tags:['síntesis','UX'],links:3,author:'Nota personal',url:'vault://nota/031',summary:'Una buena síntesis no cierra el tema: funciona como interfaz hacia la evidencia, mantiene visibles las tensiones y permite saltar a cada afirmación original.',quote:'El resumen debe ser un mapa de acceso, no el destino final.',related:['Progressive Summarization','Designing for Provenance']},
 {id:4,type:'pdf',title:'Attention Is All You Need',desc:'Arquitectura Transformer y mecanismos de atención para secuencias.',date:'26 OCT',tags:['ML','papers'],links:12,author:'Vaswani et al.',url:'arxiv.org/abs/1706.03762',summary:'El Transformer reemplaza recurrencia y convolución por atención, habilitando mayor paralelización y mejor rendimiento en traducción con menor costo de entrenamiento.',quote:'El modelo se apoya enteramente en un mecanismo de atención para obtener dependencias globales.',related:['The Annotated Transformer','Scaling Laws for Neural Language Models']},
 {id:5,type:'link',title:'A Pattern Language for Knowledge Work',desc:'Patrones recurrentes para capturar, conectar y recuperar ideas.',date:'23 OCT',tags:['sistemas','notas'],links:8,author:'Andy Matuschak',url:'notes.andymatuschak.org',summary:'Las notas duraderas deben escribirse para una audiencia futura, conectarse por ideas específicas y evolucionar mediante uso. El sistema funciona mejor como práctica que como archivo.',quote:'Las notas deben sorprenderte cuando vuelvas a encontrarlas.',related:['Evergreen Notes','Tools for thought as cultural practices']},
 {id:6,type:'note',title:'Preguntas para investigar: memoria externa',desc:'Lista abierta de preguntas sobre cognición distribuida y recuperación.',date:'20 OCT',tags:['preguntas','cognición'],links:2,author:'Nota personal',url:'vault://nota/024',summary:'La línea de investigación compara memoria externa, recuperación contextual y el costo cognitivo de mantener taxonomías manuales.',quote:'¿Qué debe recordar la persona y qué debe recordar el sistema?',related:['The Extended Mind','Where Good Ideas Come From']}
];
let selected=1,filter='all';
const cards=document.querySelector('#cards'),detail=document.querySelector('#detail'),search=document.querySelector('#search');
const labels={pdf:'PDF',link:'ENLACE',note:'NOTA'};
function renderCards(){const q=search.value.toLowerCase();const list=sources.filter(s=>(filter==='all'||s.type===filter)&&(`${s.title} ${s.desc} ${s.tags.join(' ')}`.toLowerCase().includes(q)));cards.innerHTML=list.map(s=>`<article class="card ${s.id===selected?'selected':''}" data-id="${s.id}"><div class="card-top"><span class="type ${s.type}">${labels[s.type]}</span><span class="date">${s.date}</span></div><h3>${s.title}</h3><p>${s.desc}</p><div class="tags">${s.tags.map(t=>`<span class="tag">${t}</span>`).join('')}<span class="connections">⌘ ${s.links}</span></div></article>`).join('')||'<p>No hay fuentes que coincidan.</p>';document.querySelectorAll('.card').forEach(c=>c.onclick=()=>{selected=+c.dataset.id;renderCards();renderDetail()})}
function renderDetail(){const s=sources.find(x=>x.id===selected);detail.innerHTML=`<div class="detail-cover"></div><div class="detail-body"><span class="type ${s.type}">${labels[s.type]}</span><h2>${s.title}</h2><div class="source-link">${s.author} · ${s.url}</div><div class="summary"><h4>RESUMEN SINTÉTICO</h4><p>${s.summary} <span class="cite">[1]</span></p></div><div class="quote">“${s.quote}” <span class="cite">[p. 3]</span></div><div class="related"><h4>RELACIONES · ${s.links}</h4>${s.related.map((r,i)=>`<div class="related-item"><i style="background:${i?'#c6a849':'#e77b45'}"></i><span>${r}</span></div>`).join('')}</div></div>`}
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelector('.tab.active').classList.remove('active');t.classList.add('active');filter=t.dataset.filter;renderCards()});search.oninput=renderCards;
document.querySelector('#viewToggle').onclick=()=>cards.classList.toggle('list');
const dialog=document.querySelector('#addDialog');document.querySelector('#addBtn').onclick=()=>dialog.showModal();
document.querySelector('#saveBtn').onclick=e=>{const form=document.querySelector('#addForm');if(!form.reportValidity()){e.preventDefault();return}const fd=new FormData(form);sources.unshift({id:Date.now(),type:fd.get('kind'),title:fd.get('title'),desc:(fd.get('content')||'Nueva fuente añadida al vault.').slice(0,90),date:'AHORA',tags:(fd.get('tags')||'sin etiqueta').split(',').map(x=>x.trim()),links:0,author:'Añadido por ti',url:'vault://nueva-fuente',summary:'Esta fuente está lista para procesar. El resumen aparecerá aquí con citas a los fragmentos relevantes.',quote:'Pendiente de extracción y análisis.',related:['Sin relaciones todavía']});selected=sources[0].id;setTimeout(()=>{renderCards();renderDetail();form.reset();showToast('Fuente añadida al vault')},0)};
function showToast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
renderCards();renderDetail();

